@startuml

class Elevator {
  + direction : string
}

class Button {
  + isLit : boolean
}

class ElevatorButton extends Button {}

class FloorButton extends Button {
  + floorNumber : int
  + direction : string
}

class Floor {
  + floorNumber : int
}

class ControlSystem {}

ControlSystem "1" -- "*" Elevator : manages
Elevator "1" *-- "*" ElevatorButton : has
Floor "1" *-- "2" FloorButton : has

@enduml

